from __future__ import annotations

from collections import Counter

from .model import Case, Cell, Plan, Query, Rows, validate_case

_SOURCES = {
    "single": "t",
    "inner": "t INNER JOIN u ON t.k = u.k",
    "left": "t LEFT JOIN u ON t.k = u.k",
}
_BINARY = {"add": "+", "sub": "-", "eq": "=", "ne": "<>", "lt": "<",
           "le": "<=", "gt": ">", "ge": ">=", "and": "AND", "or": "OR"}
_AGG_SQL = {"count": "COUNT", "sum": "SUM", "avg": "AVG", "min": "MIN", "max": "MAX"}
_STAT_WIDTH = {"count": 1, "sum": 2, "avg": 2, "min": 1, "max": 1}
# Emitted in place of an aggregate when partition results are structurally
# impossible (wrong width or non-numeric statistics); never equals SQLite output.
MALFORMED = "tlp:malformed-partition-result"


class _Sql:
    """Accumulates SQL text fragments with positional parameters in order."""

    def __init__(self) -> None:
        self.parts: list[str] = []
        self.params: list[Cell] = []

    def text(self, value: str) -> "_Sql":
        self.parts.append(value)
        return self

    def expr(self, expr: list) -> "_Sql":
        emit_expr(expr, self)
        return self

    def query(self) -> Query:
        return Query("".join(self.parts), tuple(self.params))


def emit_expr(expr: list, out: _Sql) -> None:
    op = expr[0]
    if op == "col":
        out.text(f"{expr[1]}.{expr[2]}")
    elif op == "lit":
        out.text("?")
        out.params.append(expr[1])
    elif op == "agg":
        out.text(_AGG_SQL[expr[1]] + "(")
        if expr[2] is None:
            out.text("*")
        else:
            emit_expr(expr[2], out)
        out.text(")")
    elif op == "not":
        out.text("(NOT ")
        emit_expr(expr[1], out)
        out.text(")")
    elif op == "isnull":
        out.text("(")
        emit_expr(expr[1], out)
        out.text(" IS NULL)")
    elif op in _BINARY:
        out.text("(")
        emit_expr(expr[1], out)
        out.text(f" {_BINARY[op]} ")
        emit_expr(expr[2], out)
        out.text(")")
    else:  # pragma: no cover - validate_case rejects these first
        raise ValueError(f"unsupported expression {op!r}")


def _list(out: _Sql, exprs: list) -> None:
    for i, expr in enumerate(exprs):
        if i:
            out.text(", ")
        out.expr(expr)


def _condition(out: _Sql, where: list | None, pred: list | None, kind: str | None) -> None:
    """Append a boolean condition: W, P, NOT P or P IS NULL, conjoined with W."""
    pieces = []
    if where is not None:
        pieces.append(("(", where, ")"))
    if kind == "true":
        pieces.append(("(", pred, ")"))
    elif kind == "false":
        pieces.append(("NOT (", pred, ")"))
    elif kind == "unknown":
        pieces.append(("((", pred, ") IS NULL)"))
    for i, (pre, expr, post) in enumerate(pieces):
        if i:
            out.text(" AND ")
        out.text(pre).expr(expr).text(post)


def _row_stage(case: Case, kind: str | None, head: list, distinct: bool = False) -> Query:
    """SELECT <head> FROM source [WHERE W [AND partition]] [GROUP BY groups]."""
    out = _Sql().text("SELECT DISTINCT " if distinct else "SELECT ")
    _list(out, head)
    out.text(" FROM " + _SOURCES[case["source"]])
    if case["where"] is not None or kind is not None:
        out.text(" WHERE ")
        _condition(out, case["where"], case["predicate"], kind)
    if case["group_by"]:
        out.text(" GROUP BY ")
        _list(out, case["group_by"])
    return out.query()


def _having(case: Case, kind: str | None) -> Query:
    out = _Sql().text("SELECT ")
    _list(out, case["select"])
    out.text(" FROM " + _SOURCES[case["source"]])
    if case["where"] is not None:
        out.text(" WHERE ")
        _condition(out, case["where"], None, None)
    if case["group_by"]:
        out.text(" GROUP BY ")
        _list(out, case["group_by"])
    if kind is not None:
        out.text(" HAVING ")
        _condition(out, None, case["predicate"], kind)
    return out.query()


def _agg(fn: str, value: list | None) -> list:
    return ["agg", fn, value]


def compile_case(case: Case) -> Plan:
    validate_case(case)
    mode = case["mode"]
    kinds = ("true", "false", "unknown")
    if mode == "having":
        base = _having(case, None)
        parts = tuple(_having(case, kind) for kind in kinds)
    elif mode in ("rows", "distinct"):
        base = _row_stage(case, None, case["select"], distinct=mode == "distinct")
        parts = tuple(_row_stage(case, kind, case["select"], distinct=mode == "distinct")
                      for kind in kinds)
    elif mode == "group":
        base = _row_stage(case, None, case["group_by"])
        parts = tuple(_row_stage(case, kind, case["group_by"]) for kind in kinds)
    else:
        groups, value = list(case["group_by"]), case["value"]
        base = _row_stage(case, None, groups + [_agg(mode, value)])
        if mode in ("sum", "avg"):
            stats = [_agg("sum", value), _agg("count", value)]
        else:
            stats = [_agg(mode, value)]
        parts = tuple(_row_stage(case, kind, groups + stats) for kind in kinds)
    return Plan(base=base, parts=parts, mode=mode, group_count=len(case["group_by"]))


def cell_key(value: Cell) -> tuple:
    """Hashable, type-sensitive identity for a result cell."""
    if value is None:
        return ("null",)
    if isinstance(value, (bool, int, float, str, bytes)):
        return (type(value).__name__, value)
    return (type(value).__name__, repr(value))


def row_key(row) -> tuple:
    return tuple(cell_key(value) for value in row)


def _order(value: Cell) -> tuple:
    """SQLite cross-type ordering: NULL < numbers < text < blob."""
    if value is None:
        return (0, 0)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return (1, value)
    if isinstance(value, str):
        return (2, value)
    if isinstance(value, bytes):
        return (3, value)
    return (4, repr(value))


def _is_number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _dedupe(rows) -> Rows:
    seen, out = set(), []
    for row in rows:
        key = row_key(row)
        if key not in seen:
            seen.add(key)
            out.append(list(row))
    return out


def compose(plan: Plan, partition_rows: list[Rows]) -> Rows:
    if len(partition_rows) != 3:
        raise ValueError("exactly three partition results are required")
    mode, width = plan.mode, plan.group_count
    if mode in ("rows", "having"):
        return [list(row) for part in partition_rows for row in part]
    if mode in ("distinct", "group"):
        return _dedupe(row for part in partition_rows for row in part)
    if mode not in _STAT_WIDTH:
        raise ValueError(f"unknown plan mode {mode!r}")

    states: dict[tuple, dict] = {}

    def state(group: list) -> dict:
        key = row_key(group)
        if key not in states:
            states[key] = {"group": list(group), "total": None, "count": 0,
                           "best": None, "bad": False}
        return states[key]

    if width == 0:
        state([])  # ungrouped aggregates always produce exactly one row
    for part in partition_rows:
        for row in part:
            row = list(row)
            entry = state(row[:width])
            stats = row[width:]
            if len(stats) != _STAT_WIDTH[mode]:
                entry["bad"] = True
                continue
            if mode == "count":
                if not _is_number(stats[0]):
                    entry["bad"] = True
                else:
                    entry["count"] += stats[0]
            elif mode in ("sum", "avg"):
                total, count = stats
                if (not _is_number(count) or (total is not None and not _is_number(total))
                        or (total is None) != (count == 0)):
                    entry["bad"] = True
                    continue
                entry["count"] += count
                if total is not None:
                    entry["total"] = total if entry["total"] is None else entry["total"] + total
            else:
                value = stats[0]
                if value is None:
                    continue
                best = entry["best"]
                if best is None:
                    entry["best"] = value
                elif mode == "min" and _order(value) < _order(best):
                    entry["best"] = value
                elif mode == "max" and _order(value) > _order(best):
                    entry["best"] = value

    out: Rows = []
    for entry in states.values():
        if entry["bad"]:
            result: Cell = MALFORMED
        elif mode == "count":
            result = entry["count"]
        elif mode in ("sum", "avg"):
            if entry["count"] == 0 or entry["total"] is None:
                result = None
            elif mode == "sum":
                result = entry["total"]
            else:
                result = entry["total"] / entry["count"]
        else:
            result = entry["best"]
        out.append(entry["group"] + [result])
    return out


def equivalent(expected: Rows, actual: Rows) -> bool:
    return Counter(row_key(row) for row in expected) == Counter(row_key(row) for row in actual)
EOF

