from __future__ import annotations

import json
import os
import tempfile
from pathlib import Path

from . import storage
from .compiler import compile_case, compose, equivalent
from .model import Case, Executor, validate_case

_RESULT_KEYS = {"ok", "expected", "actual"}
_ARTIFACT_KEYS = {"version", "case", "result"}


def _rows(value: object, label: str) -> list:
    if not isinstance(value, list) or not all(isinstance(row, (list, tuple)) for row in value):
        raise TypeError(f"executor returned malformed rows for {label}: {value!r}")
    return [list(row) for row in value]


def run_case(case: Case, executor: Executor | None = None) -> dict:
    plan = compile_case(case)  # validates before any SQL is run
    run = executor if executor is not None else storage.execute
    connection = storage.open_database(case)
    try:
        expected = _rows(run(connection, plan.base), "baseline")
        parts = [_rows(run(connection, query), name)
                 for query, name in zip(plan.parts, ("true", "false", "unknown"))]
    finally:
        connection.close()
    actual = compose(plan, parts)
    return {"ok": equivalent(expected, actual), "expected": expected, "actual": actual}


def _check_result(result: object) -> None:
    if not isinstance(result, dict) or set(result) != _RESULT_KEYS:
        raise ValueError("result must have exactly ok/expected/actual")
    if not isinstance(result["ok"], bool):
        raise ValueError("result ok must be a boolean")
    for key in ("expected", "actual"):
        rows = result[key]
        if not isinstance(rows, list) or not all(isinstance(row, list) for row in rows):
            raise ValueError(f"result {key} must be a list of rows")


def _write_json(path: Path, payload: object) -> None:
    text = json.dumps(payload, ensure_ascii=True, allow_nan=False, indent=1) + "\n"
    path.parent.mkdir(parents=True, exist_ok=True)
    handle, temp = tempfile.mkstemp(prefix=".tmp-", dir=path.parent)
    try:
        with os.fdopen(handle, "w", encoding="utf-8") as stream:
            stream.write(text)
        os.replace(temp, path)
    except BaseException:
        try:
            os.unlink(temp)
        except FileNotFoundError:
            pass
        raise


def save_failure(path: str | Path, case: Case, result: dict) -> None:
    validate_case(case)
    _check_result(result)
    if result["ok"] or equivalent(result["expected"], result["actual"]):
        raise ValueError("only mismatching results can be saved as failures")
    _write_json(Path(path), {"version": 1, "case": case, "result": result})


def load_artifact(path: str | Path) -> dict:
    path = Path(path)
    if not path.is_file():
        raise FileNotFoundError(f"replay artifact not found: {path}")
    try:
        artifact = json.loads(path.read_text(encoding="utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError(f"malformed replay artifact {path}: {error}") from error
    if not isinstance(artifact, dict) or set(artifact) != _ARTIFACT_KEYS:
        raise ValueError("artifact must have exactly version/case/result")
    if type(artifact["version"]) is not int or artifact["version"] != 1:
        raise ValueError("unsupported artifact version")
    _check_result(artifact["result"])
    validate_case(artifact["case"])
    return artifact


def replay(path: str | Path, executor: Executor | None = None) -> dict:
    artifact = load_artifact(path)
    # The recorded result is deliberately ignored: rebuild and rerun from the case.
    return run_case(artifact["case"], executor)
