from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from . import generator, runner


class _Parser(argparse.ArgumentParser):
    def error(self, message: str):  # report usage errors as exit code 2 without raising
        self.print_usage(sys.stderr)
        raise _UsageError(f"{self.prog}: error: {message}")


class _UsageError(Exception):
    pass


def _parser() -> argparse.ArgumentParser:
    parser = _Parser(prog="python -m tlp", description="SQLite TLP testing tool")
    commands = parser.add_subparsers(dest="command", required=True, parser_class=_Parser)
    campaign = commands.add_parser("campaign", help="generate and run test cases")
    campaign.add_argument("--seed", type=int, required=True)
    campaign.add_argument("--count", type=int, required=True)
    campaign.add_argument("--out", type=Path, required=True)
    rerun = commands.add_parser("replay", help="rerun a saved mismatch artifact")
    rerun.add_argument("artifact", type=Path)
    return parser


def _jsonl(cases: list) -> str:
    return "".join(json.dumps(case, ensure_ascii=True, separators=(",", ":")) + "\n"
                   for case in cases)


def _campaign(seed: int, count: int, out: Path) -> int:
    cases = generator.generate(seed, count)
    if out.exists() and (not out.is_dir() or any(out.iterdir())):
        print(f"error: output directory {out} exists and is not empty", file=sys.stderr)
        return 2
    results = []
    for index, case in enumerate(cases):
        try:
            results.append(runner.run_case(case))
        except Exception as error:
            print(f"error: case {index} failed to execute: {type(error).__name__}: {error}",
                  file=sys.stderr)
            return 2
    mismatches = [i for i, result in enumerate(results) if not result["ok"]]
    out.mkdir(parents=True, exist_ok=True)
    if any(out.iterdir()):
        print(f"error: output directory {out} became non-empty", file=sys.stderr)
        return 2
    (out / "cases.jsonl").write_text(_jsonl(cases), encoding="utf-8")
    for index in mismatches:
        runner.save_failure(out / f"failure-{index:06d}.json", cases[index], results[index])
    summary = {"version": 1, "seed": seed, "requested": count, "executed": len(results),
               "passed": len(results) - len(mismatches), "mismatches": len(mismatches)}
    (out / "summary.json").write_text(json.dumps(summary) + "\n", encoding="utf-8")
    print(json.dumps(summary))
    for index in mismatches:
        print(f"mismatch: case {index} -> {out / f'failure-{index:06d}.json'}", file=sys.stderr)
    return 1 if mismatches else 0


def _replay(path: Path) -> int:
    result = runner.replay(path)
    print(json.dumps(result, ensure_ascii=True))
    return 0 if result["ok"] else 1


def main(argv: list[str] | None = None) -> int:
    try:
        args = _parser().parse_args(sys.argv[1:] if argv is None else argv)
    except _UsageError as error:
        print(str(error), file=sys.stderr)
        return 2
    except SystemExit as exit_:  # --help
        return exit_.code if isinstance(exit_.code, int) else 2
    try:
        if args.command == "campaign":
            return _campaign(args.seed, args.count, args.out)
        return _replay(args.artifact)
    except Exception as error:
        print(f"error: {type(error).__name__}: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
EOF

