"""Execution-based measurements of generated cases (partition occupancy etc.)."""
from __future__ import annotations

import sqlite3
from collections import Counter

from .compiler import _SOURCES, _Sql, _condition, compile_case, row_key
from .model import Case, Query

_PARTS = ("true", "false", "unknown")


def expr_depth(expr: object) -> int:
    if not isinstance(expr, list):
        return 0
    children = [expr_depth(child) for child in expr[1:] if isinstance(child, list)]
    return 1 + max(children, default=0)


def expr_ops(expr: object) -> list[str]:
    if not isinstance(expr, list) or not expr:
        return []
    found = [expr[0]]
    for child in expr[1:]:
        found.extend(expr_ops(child))
    return found


class Probe:
    """A reusable in-memory database holding one candidate case's tables."""

    def __init__(self) -> None:
        self.connection = sqlite3.connect(":memory:")
        for table in ("t", "u"):
            self.connection.execute(
                f"CREATE TABLE {table}(id INTEGER, k INTEGER, v INTEGER, tag TEXT)")

    def close(self) -> None:
        self.connection.close()

    def load(self, tables: dict) -> None:
        for table in ("t", "u"):
            self.connection.execute(f"DELETE FROM {table}")
            self.connection.executemany(
                f"INSERT INTO {table} VALUES (?, ?, ?, ?)", tables[table])

    def run(self, query: Query) -> list[list]:
        return [list(row) for row in self.connection.execute(query.sql, query.params)]

    def values(self, source: str, where: list | None, expr: list,
               groups: list | None = None) -> list:
        """Values of expr over filtered rows, or per group when groups is given."""
        out = _Sql().text("SELECT ").expr(expr).text(" FROM " + _SOURCES[source])
        if where is not None:
            out.text(" WHERE ")
            _condition(out, where, None, None)
        if groups:
            out.text(" GROUP BY ")
            for i, group in enumerate(groups):
                out.text(", " if i else "").expr(group)
        return [row[0] for row in self.run(out.query())]

    def measure(self, case: Case) -> dict:
        """Measure partition occupancy and the semantic diversity properties."""
        source, where, pred = case["source"], case["where"], case["predicate"]
        plan = compile_case(case)
        out = _Sql().text("SELECT COUNT(*)")
        if case["value"] is not None:
            out.text(", COUNT(").expr(case["value"]).text(")")
        else:
            out.text(", 0")
        out.text(" FROM " + _SOURCES[source])
        if where is not None:
            out.text(" WHERE ")
            _condition(out, where, None, None)
        n_input, n_value = self.run(out.query())[0]
        info = {"input": n_input, "nonnull_value": n_value}
        if case["mode"] == "having":
            parts = [self.run(query) for query in plan.parts]
            base = self.run(plan.base)
            info["parts"] = [len(rows) for rows in parts]
            info["dup"] = any(n > 1 for n in Counter(map(row_key, base)).values())
            return info
        counts = []
        for kind in _PARTS:
            q = _Sql().text("SELECT COUNT(*) FROM " + _SOURCES[source] + " WHERE ")
            _condition(q, where, pred, kind)
            counts.append(self.run(q.query())[0][0])
        info["parts"] = counts
        if case["mode"] in ("rows", "distinct"):
            q = _Sql().text("SELECT ")
            for i, expr in enumerate(case["select"]):
                q.text(", " if i else "").expr(expr)
            q.text(" FROM " + _SOURCES[source])
            if where is not None:
                q.text(" WHERE ")
                _condition(q, where, None, None)
            projected = self.run(q.query())
            info["dup"] = any(n > 1 for n in Counter(map(row_key, projected)).values())
        if case["mode"] == "group":
            seen = Counter()
            for query in plan.parts:
                seen.update({row_key(row) for row in self.run(query)})
            info["shared"] = any(n > 1 for n in seen.values())
        return info


def three_way(info: dict) -> bool:
    return all(n > 0 for n in info["parts"])
