from __future__ import annotations

import copy
import hashlib
import random
from dataclasses import dataclass

from .analysis import Probe, expr_depth, expr_ops, three_way
from .model import AGGREGATES, COLUMNS, SOURCES, Case, validate_case

_TAGS = ("", "a", "A", "a ", " a", "b", "B", "ab", "abc", "O'Brien", 'say "hi"',
         "x\x00y", "na\u00efve", "\u65e5\u672c", "10", "9", "-1", "0", "1",
         "\U0001F600", "%_", "NULL", " ", "Zz", "q" * 32)
_REQUIRED_OPS = ("eq", "lt", "and", "or", "not", "isnull")
_COMPARISONS = ("eq", "ne", "lt", "le", "gt", "ge")
_STRICT_ATTEMPTS = 120
_ATTEMPTS = 360


@dataclass(frozen=True)
class _Slot:
    mode: str
    target: str
    groups: int
    where: bool
    source: str
    op: str
    deep: bool
    star: bool


def _slots() -> list[_Slot]:
    """One stratified block of 112 cases covering the published support matrix."""
    plan = [
        ("rows", ["dup"] * 4 + ["empty"] + ["three"] * 7),
        ("distinct", ["dup"] * 4 + ["empty"] + ["three"] * 7),
        ("count", ["allnull"] * 2 + ["empty"] * 2 + ["three"] * 8),
        ("sum", ["allnull"] * 2 + ["empty"] + ["three"] * 9),
        ("avg", ["allnull"] * 2 + ["empty"] + ["three"] * 9),
        ("min", ["allnull"] + ["empty"] + ["three"] * 10),
        ("max", ["allnull"] + ["empty"] + ["three"] * 10),
        ("group", ["shared"] * 9 + ["empty"] + ["three"] * 3),
        ("having", ["having3"] * 7 + ["hdup"] * 5 + ["ungrouped"] * 3),
    ]
    slots, n = [], 0
    for mode, targets in plan:
        for i, target in enumerate(targets):
            if mode in AGGREGATES:
                groups = i % 3
            elif mode == "group":
                groups = 1 + i % 2
            elif mode == "having":
                groups = 0 if target == "ungrouped" else 1 + i % 2
            else:
                groups = 0
            slots.append(_Slot(
                mode=mode, target=target, groups=groups, where=i % 5 in (1, 3),
                source=SOURCES[n % 3], op=_REQUIRED_OPS[n % 6], deep=n % 4 != 0,
                star=mode == "count" and target == "three" and i % 2 == 0))
            n += 1
    return slots


_BLOCK = _slots()


def _rng_for(seed: int) -> random.Random:
    # Hash the seed so negative seeds differ from their absolute values.
    digest = hashlib.sha256(f"tlp-generator-v1:{seed}".encode()).digest()
    return random.Random(int.from_bytes(digest, "big"))


def generate(seed: int, count: int) -> list[Case]:
    if type(seed) is not int or not -2**63 <= seed < 2**63:
        raise ValueError("seed must be a signed 64-bit integer")
    if type(count) is not int or not 0 <= count <= 4096:
        raise ValueError("count must be an integer in [0, 4096]")
    rng = _rng_for(seed)
    cases: list[Case] = []
    probe = Probe()
    try:
        while len(cases) < count:
            block = list(_BLOCK)
            rng.shuffle(block)
            for slot in block[:count - len(cases)]:
                cases.append(_Builder(rng, probe, slot).build())
    finally:
        probe.close()
    return cases


class _Builder:
    """Builds one case for a slot, retrying until execution confirms its target."""

    def __init__(self, rng: random.Random, probe: Probe, slot: _Slot) -> None:
        self.rng, self.probe, self.slot = rng, probe, slot
        self.source = slot.source
        self.tables: dict = {"t": [], "u": []}
        self.where: list | None = None
        self.groups: list = []

    # ------------------------------------------------------------------ data
    def _row(self, i: int, kdom: list, vdom: list, tags: list, pnull: float) -> list:
        rng = self.rng
        ident = None if rng.random() < 0.05 else (
            i + 1 if rng.random() < 0.8 else rng.randint(1, i + 1))
        k = None if rng.random() < pnull else rng.choice(kdom)
        v = None if rng.random() < pnull + 0.05 else rng.choice(vdom)
        tag = None if rng.random() < pnull else rng.choice(tags)
        return [ident, k, v, tag]

    def _make_tables(self) -> None:
        rng = self.rng
        kdom = rng.sample(range(-3, 8), rng.choice((2, 3, 3, 4)))
        if rng.random() < 0.1:
            kdom.append(rng.choice((-1000, 1000)))
        vdom = rng.sample(range(-6, 9), rng.choice((3, 4, 5)))
        if rng.random() < 0.25:
            vdom.append(rng.choice((-1000, 1000, 999, -999)))
        tags = rng.sample(_TAGS, rng.choice((2, 3, 4)))
        pnull = rng.choice((0.1, 0.15, 0.2, 0.3))
        t = [self._row(i, kdom, vdom, tags, pnull) for i in range(rng.randint(4, 14))]
        udom = kdom + [rng.randint(-3, 9)]
        u = [self._row(i, udom, vdom, tags, pnull) for i in range(rng.randint(2, 8))]
        for rows in (t, u):
            for _ in range(rng.choice((0, 0, 1, 2))):
                rows.append(list(rng.choice(rows)))
        if self.slot.mode == "having" and rng.random() < 0.7:
            # A group whose aggregated values are all NULL yields an unknown predicate.
            dead = rng.choice(kdom)
            for row in t:
                if row[1] == dead:
                    row[2] = None
        rng.shuffle(t)
        self.tables = {"t": t[:32], "u": u[:32]}
        self.probe.load(self.tables)

    # ----------------------------------------------------------- expressions
    def _tables(self) -> list[str]:
        return ["t"] if self.source == "single" else ["t", "t", "u"]

    def _col(self, kind: str) -> list:
        table = self.rng.choice(self._tables())
        if kind == "text":
            return ["col", table, "tag"]
        return ["col", table, self.rng.choice(("v", "v", "k", "id"))]

    def _random_lit(self, kind: str) -> list:
        rng = self.rng
        if kind == "text":
            return ["lit", rng.choice(_TAGS)]
        if rng.random() < 0.1:
            return ["lit", rng.choice((-1000, 1000, 0))]
        return ["lit", rng.randint(-6, 9)]

    def _lit_from(self, values: list, kind: str) -> list:
        """A literal drawn from observed values so comparisons are not vacuous."""
        rng = self.rng
        pool = [v for v in values if v is not None and isinstance(v, str) == (kind == "text")]
        if pool and rng.random() < 0.85:
            value = rng.choice(pool)
            if isinstance(value, float):
                value = int(value)
            if isinstance(value, int):
                value = max(-1000, min(1000, value + rng.choice((0, 0, 0, 1, -1))))
            else:
                value = value[:32]
            return ["lit", value]
        return self._random_lit(kind)

    def _num(self, budget: int) -> list:
        """Row-stage numeric expression of depth <= budget."""
        rng = self.rng
        if budget >= 2 and rng.random() < 0.25:
            other = self._col("number") if rng.random() < 0.4 else self._random_lit("number")
            if other[0] == "lit" and rng.random() < 0.05:
                other = ["lit", None]
            pair = [self._num(budget - 1), other]
            if rng.random() < 0.3:
                pair.reverse()
            return [rng.choice(("add", "sub")), *pair]
        if rng.random() < 0.06:
            return self._random_lit("number")
        return self._col("number")

    def _scalar(self, budget: int) -> tuple[list, str]:
        if self.rng.random() < 0.25:
            return self._col("text"), "text"
        return self._num(budget), "number"

    def _row_cmp(self, budget: int) -> list:
        rng = self.rng
        left, kind = self._scalar(budget - 1)
        roll = rng.random()
        if roll < 0.12:
            right = self._col(kind)
        elif roll < 0.16:
            right = self._random_lit("number" if kind == "text" else "text")
        elif roll < 0.18:
            right = ["lit", None]
        else:
            right = self._lit_from(self.probe.values(self.source, self.where, left), kind)
        pair = [left, right]
        if rng.random() < 0.2:
            pair.reverse()
        return [rng.choice(_COMPARISONS), *pair]

    def _row_atom(self, budget: int) -> list:
        if self.rng.random() < 0.15:
            return ["isnull", self._scalar(budget - 1)[0]]
        return self._row_cmp(budget)

    def _pred(self, budget: int, atom) -> list:
        rng = self.rng
        if budget < 3:
            return atom(budget)
        roll = rng.random()
        if roll < 0.35:
            return atom(budget)
        if roll < 0.62:
            return ["and", self._pred(budget - 1, atom), self._pred(budget - 1, atom)]
        if roll < 0.84:
            return ["or", self._pred(budget - 1, atom), self._pred(budget - 1, atom)]
        if roll < 0.94:
            return ["not", self._pred(budget - 1, atom)]
        return ["isnull", self._pred(budget - 1, atom)]

    def _row_pred(self, budget: int) -> list:
        return self._pred(budget, self._row_atom)

    def _group_expr(self) -> list:
        rng = self.rng
        roll = rng.random()
        tables = self._tables()
        if roll < 0.4:
            return ["col", rng.choice(tables), "k"]
        if roll < 0.7:
            return ["col", rng.choice(tables), "tag"]
        if roll < 0.82:
            return [rng.choice(("add", "sub")), ["col", "t", "k"], ["lit", rng.randint(-3, 3)]]
        return ["col", rng.choice(tables), "v"]

    def _pick_groups(self, n: int) -> list:
        groups: list = []
        while len(groups) < n:
            expr = self._group_expr()
            if expr not in groups:
                groups.append(expr)
        return groups

    # ------------------------------------------------------- HAVING stage
    def _agg(self, budget: int = 3) -> list:
        rng = self.rng
        fn = rng.choice(AGGREGATES)
        if budget < 2 or (fn == "count" and rng.random() < 0.4):
            return ["agg", "count", None]
        return ["agg", fn, self._num(min(2, budget - 1))]

    def _having_scalar(self, budget: int) -> tuple[list, str]:
        rng = self.rng
        keys = [g for g in self.groups if expr_depth(g) <= budget]
        roll = rng.random()
        if keys and roll < 0.3:
            key = rng.choice(keys)
            return key, "text" if key[0] == "col" and key[2] == "tag" else "number"
        if budget >= 3 and roll < 0.42:
            return [rng.choice(("add", "sub")), self._agg(budget - 1),
                    self._random_lit("number")], "number"
        return self._agg(budget), "number"

    def _having_atom(self, budget: int) -> list:
        rng = self.rng
        left, kind = self._having_scalar(budget - 1)
        if rng.random() < 0.15:
            return ["isnull", left]
        if rng.random() < 0.1:
            right = self._having_scalar(budget - 1)[0]
        else:
            values = self.probe.values(self.source, self.where, left, self.groups)
            right = self._lit_from(values, kind)
        return [rng.choice(_COMPARISONS), left, right]

    def _having_select(self) -> list:
        rng = self.rng
        dup = self.slot.target == "hdup"
        select = []
        for _ in range(rng.choice((1, 1, 2) if dup else (1, 2, 3))):
            roll = rng.random()
            if self.groups and roll < (0.15 if dup else 0.35):
                select.append(rng.choice(self.groups))
            elif dup and roll < 0.5:
                select.append(rng.choice((["agg", "count", None], ["lit", rng.randint(0, 3)],
                                          ["agg", "min", ["col", "t", "v"]])))
            elif roll < 0.55:
                select.append(self._random_lit(rng.choice(("number", "text"))))
            elif roll < 0.7:
                select.append([rng.choice(("add", "sub")), self._agg(), self._random_lit("number")])
            else:
                select.append(self._agg())
        if not self.groups and not any("agg" in expr_ops(e) for e in select):
            select[0] = self._agg()
        return select

    # ---------------------------------------------------------------- cases
    def _where(self) -> list | None:
        if not self.slot.where:
            return None
        rng = self.rng
        if self.slot.target == "empty" and rng.random() < 0.5:
            column = self._col("number")
            values = [v for v in self.probe.values(self.source, None, column) if v is not None]
            return rng.choice((
                ["lt", column, ["lit", min(values, default=0)]],
                ["and", ["isnull", column], ["not", ["isnull", column]]],
                ["eq", column, ["lit", 1000 if 1000 not in values else -1000]],
            ))
        return self._row_pred(rng.choice((2, 3, 3, 4)))

    def _allnull_value(self) -> list:
        """Pick a numeric value and blank its referenced column in the data."""
        rng = self.rng
        table = rng.choice(self._tables())
        column = rng.choice(("v", "id"))
        value = ["col", table, column]
        if rng.random() < 0.3:
            value = [rng.choice(("add", "sub")), value, self._random_lit("number")]
        index = COLUMNS.index(column)
        for row in self.tables[table]:
            row[index] = None
        self.probe.load(self.tables)
        return value

    def _candidate(self) -> Case:
        rng, slot = self.rng, self.slot
        self._make_tables()
        if slot.target == "empty":
            how = rng.random()
            if how < 0.3:
                self.tables["t"] = []
            elif how < 0.5 and self.source == "inner":
                self.tables["u"] = [[r[0], 500 + i, r[2], r[3]]
                                    for i, r in enumerate(self.tables["u"])]
            self.probe.load(self.tables)
        self.where = self._where()
        self.groups = self._pick_groups(slot.groups)
        budget = rng.choice((3, 4, 5, 5)) if slot.deep else rng.choice((2, 3, 4))
        case: Case = {
            "version": 1, "tables": self.tables, "source": self.source,
            "predicate": None, "where": self.where, "mode": slot.mode,
            "select": [], "value": None, "group_by": self.groups,
        }
        if slot.mode == "having":
            case["predicate"] = self._pred(budget, self._having_atom)
            case["select"] = self._having_select()
            return case
        case["predicate"] = self._row_pred(budget)
        if slot.mode in ("rows", "distinct"):
            size = rng.choice((1, 1, 2, 3))
            if slot.target == "dup":
                case["select"] = [rng.choice((self._group_expr(), self._col("text")))
                                  for _ in range(size)]
            else:
                case["select"] = [self._scalar(rng.choice((1, 2, 3)))[0] for _ in range(size)]
        elif slot.mode == "group":
            case["select"] = copy.deepcopy(self.groups)
        elif not slot.star:
            if slot.target == "allnull":
                case["value"] = self._allnull_value()
            else:
                case["value"] = self._num(rng.choice((1, 1, 2, 3)))
        return case

    def _accept(self, case: Case, info: dict, strict: bool) -> bool:
        slot, target = self.slot, self.slot.target
        if strict:
            if slot.op not in expr_ops(case["predicate"]):
                return False
            if slot.deep and expr_depth(case["predicate"]) < 3:
                return False
        if target == "empty":
            return info["input"] == 0
        if target in ("having3", "hdup", "ungrouped"):
            if target == "having3" and not three_way(info):
                return False
            if target == "hdup" and not info["dup"]:
                return False
            if strict and slot.where and info["input"] < 2:
                return False
            if strict and target == "hdup":
                return sum(n > 0 for n in info["parts"]) >= 2
            if strict and target == "ungrouped":
                return info["input"] > 0
            return True
        if strict and (not three_way(info) or (slot.where and info["input"] < 3)):
            return False
        if target == "three":
            return three_way(info)
        if target == "allnull":
            return info["input"] > 0 and info["nonnull_value"] == 0
        if target == "dup":
            return info["dup"]
        if target == "shared":
            return info["shared"]
        raise AssertionError(target)

    def build(self) -> Case:
        for attempt in range(_ATTEMPTS):
            case = self._candidate()
            try:
                validate_case(case)
            except ValueError:
                continue
            if self._accept(case, self.probe.measure(case), attempt < _STRICT_ATTEMPTS):
                return case
        return self._fallback()

    # -------------------------------------------------------------- fallback
    def _fallback(self) -> Case:
        """Deterministic construction guaranteeing the slot's primary property."""
        slot = self.slot
        t = [[1, 1, 5, "a"], [2, 1, -5, "a"], [3, 1, None, "b"],
             [4, 2, -5, "b"], [5, 3, None, None], [6, 3, None, "a"]]
        u = [[1, 1, 7, "x"], [2, 2, 8, "y"], [3, 3, None, "z"]]
        case: Case = {
            "version": 1, "tables": {"t": t, "u": u}, "source": slot.source,
            "predicate": ["lt", ["col", "t", "v"], ["lit", 0]], "where": None,
            "mode": slot.mode, "select": [], "value": None, "group_by": [],
        }
        if slot.target == "empty":
            case["tables"]["t"] = []
        if slot.mode in ("rows", "distinct"):
            case["select"] = [["col", "t", "k"]]
        elif slot.mode == "group":
            case["group_by"] = [["col", "t", "k"]]
            case["select"] = [["col", "t", "k"]]
        elif slot.mode == "having":
            total = ["agg", "sum", ["col", "t", "v"]]
            case["predicate"] = ["gt", ["agg", "max", ["col", "t", "v"]], ["lit", 0]]
            if slot.target == "ungrouped":
                case["select"] = [total]
            else:
                case["group_by"] = [["col", "t", "k"]]
                case["select"] = ([["agg", "count", ["col", "t", "tag"]]]
                                  if slot.target == "hdup" else [["col", "t", "k"], total])
        else:
            case["group_by"] = [["col", "t", "k"]] if slot.groups else []
            if not slot.star:
                case["value"] = ["col", "t", "v"]
            if slot.target == "allnull":
                case["value"] = ["col", "t", "id"]
                for row in t:
                    row[0] = None
        validate_case(case)
        return case

"""Independent measurement of the published diversity criteria.

SQL is assembled here with inline-escaped literals rather than through
tlp.compiler, so this doubles as a cross-check of the compiled plans.
"""
from __future__ import annotations

import json
import sqlite3
from collections import Counter

FROM = {"single": "t", "inner": "t JOIN u ON t.k = u.k", "left": "t LEFT JOIN u ON t.k = u.k"}
OPS = {"add": "+", "sub": "-", "eq": "=", "ne": "!=", "lt": "<", "le": "<=", "gt": ">",
       "ge": ">=", "and": "AND", "or": "OR"}


def lit(value):
    if value is None:
        return "NULL"
    if isinstance(value, int):
        return f"({value})"
    return "CAST(X'" + value.encode("utf-8").hex() + "' AS TEXT)"


def sql(e):
    op = e[0]
    if op == "col":
        return f"{e[1]}.{e[2]}"
    if op == "lit":
        return lit(e[1])
    if op == "agg":
        return f"{e[1].upper()}({'*' if e[2] is None else sql(e[2])})"
    if op == "not":
        return f"(NOT {sql(e[1])})"
    if op == "isnull":
        return f"({sql(e[1])} IS NULL)"
    return f"({sql(e[1])} {OPS[op]} {sql(e[2])})"


def connect(case):
    db = sqlite3.connect(":memory:")
    for name in ("t", "u"):
        db.execute(f"CREATE TABLE {name}(id INTEGER, k INTEGER, v INTEGER, tag TEXT)")
        db.executemany(f"INSERT INTO {name} VALUES (?,?,?,?)", case["tables"][name])
    return db


def where_clause(case, extra=None):
    parts = []
    if case["where"] is not None:
        parts.append(f"({sql(case['where'])})")
    if extra:
        parts.append(extra)
    return (" WHERE " + " AND ".join(parts)) if parts else ""


def keyed(row):
    return tuple((type(c).__name__, c) for c in row)


def depth(e):
    if not isinstance(e, list):
        return 0
    return 1 + max([depth(c) for c in e[1:] if isinstance(c, list)], default=0)


def ops(e):
    if not isinstance(e, list):
        return set()
    out = {e[0]}
    for c in e[1:]:
        out |= ops(c)
    return out


def erase(e):
    if isinstance(e, list):
        if e and e[0] == "lit":
            return ["lit", type(e[1]).__name__]
        return [erase(c) for c in e]
    return e


def fingerprint(case):
    shape = {k: erase(v) for k, v in case.items() if k != "tables"}
    return json.dumps(shape, sort_keys=True)


def measure(case):
    db = connect(case)
    src, p = FROM[case["source"]], sql(case["predicate"])
    info = {}
    try:
        n = db.execute(f"SELECT COUNT(*) FROM {src}{where_clause(case)}").fetchone()[0]
        info["input"] = n
        if case["mode"] == "having":
            g = case["group_by"]
            gb = (" GROUP BY " + ", ".join(map(sql, g))) if g else ""
            sel = ", ".join(map(sql, case["select"]))
            base = f"SELECT {sel} FROM {src}{where_clause(case)}{gb}"
            parts = [db.execute(f"{base} HAVING {h}").fetchall()
                     for h in (f"({p})", f"NOT ({p})", f"(({p}) IS NULL)")]
            info["parts"] = [len(r) for r in parts]
            rows = db.execute(base).fetchall()
            info["dup"] = len(set(map(keyed, rows))) < len(rows)
            return info
        info["parts"] = [db.execute(f"SELECT COUNT(*) FROM {src}{where_clause(case, c)}").fetchone()[0]
                         for c in (f"({p})", f"NOT ({p})", f"(({p}) IS NULL)")]
        if case["value"] is not None:
            info["nonnull"] = db.execute(
                f"SELECT COUNT({sql(case['value'])}) FROM {src}{where_clause(case)}").fetchone()[0]
        if case["mode"] in ("rows", "distinct"):
            rows = db.execute(f"SELECT {', '.join(map(sql, case['select']))} FROM {src}"
                              f"{where_clause(case)}").fetchall()
            info["dup"] = len(set(map(keyed, rows))) < len(rows)
        if case["mode"] == "group":
            gsel = ", ".join(map(sql, case["group_by"]))
            seen = Counter()
            for c in (f"({p})", f"NOT ({p})", f"(({p}) IS NULL)"):
                rows = db.execute(f"SELECT {gsel} FROM {src}{where_clause(case, c)} GROUP BY {gsel}").fetchall()
                seen.update(set(map(keyed, rows)))
            info["shared"] = any(v > 1 for v in seen.values())
        return info
    finally:
        db.close()


AGG = ("count", "sum", "avg", "min", "max")


def check(cases):
    """Return a dict of category -> (passed, detail)."""
    infos = [measure(c) for c in cases]
    modes = Counter(c["mode"] for c in cases)
    sources = Counter(c["source"] for c in cases)
    res = {}
    res["1_modes"] = (all(modes[m] >= 8 for m in ("rows", "distinct", *AGG, "group", "having")), dict(modes))
    nwhere = sum(c["where"] is not None for c in cases)
    res["2_sources"] = (all(sources[s] >= 16 for s in FROM) and nwhere >= 16, (dict(sources), nwhere))
    grouped = [c for c in cases if c["mode"] in AGG and c["group_by"]]
    star = any(c["mode"] == "count" and c["value"] is None for c in cases)
    valued = any(c["mode"] == "count" and c["value"] is not None for c in cases)
    res["3_grouped"] = (len(grouped) >= 20 and {c["mode"] for c in grouped} == set(AGG) and star and valued,
                        len(grouped))
    allops = set().union(*(ops(c["predicate"]) for c in cases)) if cases else set()
    deep = sum(depth(c["predicate"]) >= 3 for c in cases)
    res["4_ops"] = ({"eq", "lt", "and", "or", "not", "isnull"} <= allops and deep >= 12, deep)
    fps = len({fingerprint(c) for c in cases})
    res["5_fingerprints"] = (fps >= 20, fps)
    three = sum(all(n > 0 for n in i["parts"]) for i in infos)
    nonempty = sum(i["input"] > 0 if c["mode"] != "having" else sum(i["parts"]) > 0
                   for c, i in zip(cases, infos))
    res["6_occupancy"] = (three >= 24 and nonempty >= 48, (three, nonempty))
    rowstage = [(c, i) for c, i in zip(cases, infos) if c["mode"] != "having"]
    empty = sum(i["input"] == 0 for c, i in rowstage)
    allnull = sum(c["mode"] in AGG and c["value"] is not None and i["input"] > 0 and i["nonnull"] == 0
                  for c, i in rowstage)
    dup = sum(c["mode"] in ("rows", "distinct") and i["dup"] for c, i in rowstage)
    res["7_edges"] = (empty >= 6 and allnull >= 6 and dup >= 6, (empty, allnull, dup))
    groups = [(c, i) for c, i in zip(cases, infos) if c["mode"] == "group"]
    shared = sum(i["shared"] for c, i in groups)
    gw = sum(c["where"] is not None for c, i in groups)
    res["8_group"] = (shared >= 6 and gw >= 2, (shared, gw))
    hav = [(c, i) for c, i in zip(cases, infos) if c["mode"] == "having"]
    h3 = sum(all(n > 0 for n in i["parts"]) for c, i in hav)
    hd = sum(i["dup"] for c, i in hav)
    hu = sum(not c["group_by"] for c, i in hav)
    hw = sum(c["where"] is not None for c, i in hav)
    res["9_having"] = (h3 >= 6 and hd >= 4 and hu >= 2 and hw >= 2, (h3, hd, hu, hw))
    return res

